import { describe, expect, it } from 'vitest';
import { retry } from '../src/index.ts';

describe('retry', () => {
  it('throws the last error', async () => {
    const failing = async () => {
      throw new Error('still down');
    };
    await expect(retry(failing)).rejects.toThrow('still down');
  });
});

